package com.TreinoJC.app.dao;

import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;

import com.academia.app.bd.DBHelper;
import com.TreinosJC.app.modelos.Treino;

import java.util.ArrayList;
import java.util.List;

public class TreinoDAO {

    private SQLiteDatabase db;
    private DBHelper helper;

    public TreinoDAO(Context context) {
        helper = new DBHelper(context);
    }

    public void Abrir() {
        db = helper.getWritableDatabase();
    }

    public void Fechar() {
        helper.close();
    }

    public Long Inserir(Treino t) {
        ContentValues dados = new ContentValues();
        dados.put("Nome", t.getNome());
        dados.put("Descricao", t.getDescricao());
        dados.put("UsuarioId", t.getUsuarioId());

        return db.insert("treino", null, dados);
    }

    public void Excluir(Treino t) {
        if (t.getId() <= 0) return;

        this.Abrir();
        db.delete("treino", "Id=?",
                new String[]{String.valueOf(t.getId())});
        this.Fechar();
    }

    public void Atualizar(Treino t) {
        if (t.getId() <= 0) return;

        ContentValues dados = new ContentValues();
        dados.put("Nome", t.getNome());
        dados.put("Descricao", t.getDescricao());
        dados.put("UsuarioId", t.getUsuarioId());

        this.Abrir();
        db.update("treino", dados, "Id=?",
                new String[]{String.valueOf(t.getId())});
        this.Fechar();
    }

    // Lista todos os treinos de um usuário específico
    public List<Treino> ListarPorUsuario(int usuarioId) {
        List<Treino> lista = new ArrayList<>();

        String[] campos = {"Id", "Nome", "Descricao", "UsuarioId"};
        Cursor dados = db.query("treino", campos,
                "UsuarioId=?", new String[]{String.valueOf(usuarioId)},
                null, null, "Nome");

        dados.moveToFirst();
        while (!dados.isAfterLast()) {
            Treino t = new Treino(
                    dados.getInt(0),
                    dados.getString(1),
                    dados.getString(2),
                    dados.getInt(3)
            );
            lista.add(t);
            dados.moveToNext();
        }
        dados.close();
        return lista;
    }

    public List<Treino> ListarTudo() {
        List<Treino> lista = new ArrayList<>();

        String[] campos = {"Id", "Nome", "Descricao", "UsuarioId"};
        Cursor dados = db.query("treino", campos, null, null,
                null, null, "Nome");

        dados.moveToFirst();
        while (!dados.isAfterLast()) {
            Treino t = new Treino(
                    dados.getInt(0),
                    dados.getString(1),
                    dados.getString(2),
                    dados.getInt(3)
            );
            lista.add(t);
            dados.moveToNext();
        }
        dados.close();
        return lista;
    }
}

